PIECE_NAMES = {"K": "King", "Q": "Queen", "R": "Rook", "B": "Bishop", "N": "Knight"}
PIECE_VALUES = {"Pawn": 1, "Bishop": 2, "Knight": 3, "Rook": 4, "Queen": 5, "King": 6}
RESULTS = {"1-0", "0-1", "1/2-1/2"}


def parse_moves(game: str) -> list:
    """Strip move numbers (e.g. '1.') and the final result; return the move list."""
    moves = []
    for token in game.split():
        if token.endswith(".") and token[:-1].isdigit():
            continue
        if token in RESULTS:
            continue
        moves.append(token)
    return moves


def get_n_moves(game: str) -> int:
    return len(parse_moves(game))


def _piece_name(move: str) -> str:
    """Piece moved for a single (non-castling) move."""
    first = move[0]
    return PIECE_NAMES.get(first, "Pawn")


def count_piece_moves(moves: list) -> dict:
    # Accept either the parsed move list or the raw game string.
    if isinstance(moves, str):
        moves = parse_moves(moves)
    counts = {"King": 0, "Queen": 0, "Rook": 0, "Bishop": 0, "Knight": 0, "Pawn": 0}
    for move in moves:
        bare = move.rstrip("+#")
        if bare in ("O-O", "O-O-O"):          # castling moves both king and rook
            counts["King"] += 1
            counts["Rook"] += 1
        else:
            counts[_piece_name(move)] += 1
    return counts


def _player_moves(game: str, player: str) -> list:
    moves = parse_moves(game)
    return moves[0::2] if player == "white" else moves[1::2]


def most_used_piece(game: str, player: str) -> str:
    counts = count_piece_moves(_player_moves(game, player))
    # Most moves; break ties by higher piece value.
    return max(counts, key=lambda p: (counts[p], PIECE_VALUES[p]))


def remaining_pieces(game: str, player: str) -> int:
    moves = parse_moves(game)
    # The opponent's capturing moves remove this player's pieces.
    opponent = moves[1::2] if player == "white" else moves[0::2]
    captured = sum(1 for move in opponent if "x" in move)
    return 16 - captured


def n_checks(game: str, player: str) -> int:
    player_moves = _player_moves(game, player)
    # A '+' (or a '#' checkmate) at the end means the opponent was put in check.
    return sum(1 for move in player_moves if move.endswith("+") or move.endswith("#"))

def main():
    seq = input().split()
    # Record the visit order (1-based) for each visited dot.
    order = {}
    for step, num in enumerate(seq, start=1):
        dot = int(num)
        if dot not in order:
            order[dot] = step

    cells = []
    for dot in range(1, 10):
        cells.append(f"[{order[dot]}]" if dot in order else "[ ]")

    rows = [cells[0:3], cells[3:6], cells[6:9]]
    separator = "|     |     |"
    lines = []
    for i, row in enumerate(rows):
        lines.append("---".join(row))
        if i < 2:
            lines.append(separator)
    print("\n".join(lines))


main()

